#pragma once
// Portable scalar full-width interval compiler and FIDX byte-code kernel.
#include <algorithm>
#include <array>
#include <cstdint>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <vector>

using Key = unsigned __int128;
inline std::string hexkey(Key x) {
    const char* digits = "0123456789abcdef";
    std::string s(32, '0');
    for (int i = 31; i >= 0; --i) { s[i] = digits[unsigned(x & 15)]; x >>= 4; }
    return s;
}
inline Key key(const std::string& s) {
    if (s.size() != 32) throw std::runtime_error("key width");
    Key x = 0;
    for (char c : s) {
        int d = c >= '0' && c <= '9' ? c-'0' : c >= 'a' && c <= 'f' ? c-'a'+10 : -1;
        if (d < 0) throw std::runtime_error("key digit");
        x = (x << 4) | d;
    }
    return x;
}
struct entry { Key prefix; int length, next_hop; };
inline entry make_entry(const std::string& s, int length, int hop) {
    return {key(s), length, hop};
}
struct interval_edge { Key address; int next_hop; };
inline Key edge_key(Key x) { return x; }
struct BaselineLookup {
    std::vector<interval_edge> edges;
    void build(const std::vector<entry>& fib) {
        struct Event { Key x; int length, hop; };
        std::vector<Event> events;
        events.reserve(2*fib.size()+1);
        // The sentinel ensures that the atlas always begins at zero.
        events.push_back({0, -1, -1});
        for (const auto& route : fib) {
            events.push_back({route.prefix, route.length, route.next_hop});
            if (route.length) {
                Key end = route.prefix + (Key(1) << (128-route.length));
                // Zero after unsigned addition denotes the upper endpoint U,
                // not an event at the start of the address space.
                if (end) events.push_back({end, route.length, -1});
            }
        }
        std::sort(events.begin(), events.end(), [](const Event& a, const Event& b) {
            if (a.x != b.x) return a.x < b.x;
            return a.hop < b.hop; // all ending events precede starting events
        });
        std::array<int, 129> active;
        active.fill(-1);
        edges.clear();
        for (size_t i = 0; i < events.size();) {
            size_t j = i;
            while (j < events.size() && events[j].x == events[i].x) {
                if (events[j].length >= 0) active[events[j].length] = events[j].hop;
                ++j;
            }
            int hop = -1;
            for (int l = 128; l >= 0; --l) if (active[l] >= 0) { hop = active[l]; break; }
            if (edges.empty() || edges.back().next_hop != hop) edges.push_back({events[i].x, hop});
            i = j;
        }
    }
};

struct Layout { int lo=0, span=0, mode=0, cached=0; std::vector<int> children; };
struct Answer { int hop, run; std::vector<unsigned> path; };
struct PackedResult { std::string image; std::vector<Answer> answers; };
using Bytes = std::vector<unsigned char>;
constexpr int WIDTH[3] = {16,8,4};
constexpr int LANES[3] = {4,8,16};
inline unsigned node_pages(int span, int b, int mode) {
    return (32 + 4*b + (b ? b-1 : span)*WIDTH[mode] + 63)/64;
}
inline void put(Bytes& bytes, unsigned off, Key value, unsigned width) {
    for (unsigned i=0; i<width; ++i) { bytes[off+i] = unsigned(value & 255); value >>= 8; }
}
inline Key get(const Bytes& bytes, unsigned off, unsigned width) {
    Key result=0;
    for (unsigned i=width; i>0; --i) result = (result<<8) | bytes[off+i-1];
    return result;
}
inline std::string tohex(const Bytes& bytes) {
    const char* d="0123456789abcdef";
    std::string out;
    out.reserve(bytes.size()*2);
    for (unsigned c:bytes) { out.push_back(d[c>>4]); out.push_back(d[c&15]); }
    return out;
}
inline Bytes fromhex(const std::string& image) {
    auto digit=[](char c) {return c<='9' ? c-'0' : c-'a'+10;};
    Bytes bytes(image.size()/2);
    for (size_t i=0;i<bytes.size();++i) bytes[i] = 16*digit(image[2*i])+digit(image[2*i+1]);
    return bytes;
}
// No starts, layout, or routing state is used here. Everything traversed is
// read from the packed bytes (also used by PACK and the JSON compiler).
inline Answer lookup_image(const Bytes& bytes, Key address) {
    Answer answer;
    unsigned offset=64;
    while (true) {
        answer.path.push_back(offset);
        unsigned kind=bytes[offset], mode=bytes[offset+1];
        unsigned count=unsigned(get(bytes,offset+8,2));
        Key base=get(bytes,offset+16,16);
        unsigned keys=offset+32+(kind==0 ? count*4 : 0);
        unsigned nkeys=kind==0 ? count-1 : count;
        // Upper-bound: equality advances to the right, for both kinds.
        unsigned low=0,high=nkeys;
        while (low<high) {
            unsigned mid=(low+high)/2;
            Key value=get(bytes,keys+mid*WIDTH[mode],WIDTH[mode]);
            if (mode) value+=base;
            if (value<=address) low=mid+1; else high=mid;
        }
        if (kind) {
            answer.run=unsigned(get(bytes,offset+4,2))+low-1;
            unsigned h=unsigned(get(bytes,unsigned(get(bytes,16,4))+4*answer.run,4));
            answer.hop=h==0xffffffffu ? -1 : int(h);
            return answer;
        }
        offset=unsigned(get(bytes,offset+32+4*low,4));
    }
}
inline std::vector<Answer> trace_bytes(const Bytes& bytes, const std::vector<Key>& addresses) {
    std::vector<Answer> answers;
    for (Key x:addresses) answers.push_back(lookup_image(bytes,x));
    return answers;
}
inline std::vector<Answer> trace_image(const std::string& image, const std::vector<Key>& addresses) {
    return trace_bytes(fromhex(image),addresses);
}
inline Bytes build_image(const std::vector<Key>& starts, const std::vector<int>& hops,
                         const std::vector<Layout>& nodes) {
    std::vector<unsigned> offsets;
    unsigned total=64;
    for (const auto& node:nodes) {
        offsets.push_back(total);
        total+=64*node_pages(node.span,node.children.size(),node.mode);
    }
    unsigned hopoff=total;
    total+=(4*starts.size()+63)/64*64;
    Bytes bytes(total,0);
    bytes[0]='F'; bytes[1]='I'; bytes[2]='D'; bytes[3]='X'; bytes[4]=2;
    put(bytes,8,starts.size(),4); put(bytes,12,nodes.size(),4);
    put(bytes,16,hopoff,4); put(bytes,20,total,4);
    for (size_t i=0;i<nodes.size();++i) {
        const auto& node=nodes[i];
        unsigned off=offsets[i],b=node.children.size();
        bytes[off]=b==0; bytes[off+1]=node.mode; bytes[off+2]=node.cached;
        put(bytes,off+4,node.lo,2); put(bytes,off+6,node.span,2);
        put(bytes,off+8,b ? b : node.span,2);
        put(bytes,off+12,64*node_pages(node.span,b,node.mode),4);
        Key base=starts[node.lo];
        put(bytes,off+16,base,16);
        unsigned at=off+32;
        for (int c:node.children) { put(bytes,at,offsets[c],4); at+=4; }
        unsigned nkeys=b ? b-1 : node.span;
        for (unsigned k=0;k<nkeys;++k) {
            Key value=starts[b ? nodes[node.children[k+1]].lo : node.lo+k];
            if (node.mode) value-=base;
            put(bytes,at,value,WIDTH[node.mode]); at+=WIDTH[node.mode];
        }
    }
    for (unsigned i=0;i<hops.size();++i) put(bytes,hopoff+4*i,hops[i]<0 ? 0xffffffffu : unsigned(hops[i]),4);
    return bytes;
}
inline PackedResult pack_image(const std::vector<Key>& starts, const std::vector<int>& hops,
                               const std::vector<Layout>& nodes, const std::vector<Key>& addresses) {
    Bytes bytes=build_image(starts,hops,nodes);
    return {tohex(bytes),trace_bytes(bytes,addresses)};
}
inline void print_answer(const Answer& a) {
    std::cout<<a.hop<<' '<<a.run<<' '<<a.path.size();
    for (unsigned off:a.path) std::cout<<' '<<off;
    std::cout<<'\n';
}
